def resolve_npc_name(map_id: int, name32: bytes) -> bytes:
    """Return US 1.0.282 NPC.INI key bytes for an NPC OBJECTINFO name32 field."""
    raw = name32.split(b"\x00", 1)[0]
    mapped = NPC_BY_MAP_NAME.get((map_id, raw)) or NPC_UNIQUE_NAME.get(raw)
    if mapped is not None:
        return mapped
    stripped = raw.strip()
    if stripped != raw:
        mapped = NPC_BY_MAP_NAME.get((map_id, stripped)) or NPC_UNIQUE_NAME.get(stripped)
        if mapped is not None:
            return mapped
    return raw
